const MANIFEST = {
  "type": "Media.ImageRevealClipPath",
  "description": "Image reveal effect using animated clip-path shapes with multiple reveal patterns",
  "editorElement": {
    "selector": ".image-reveal-clippath",
    "displayName": "Image Reveal Clip-Path",
    "archetype": "container",
    "data": {
      "image": {
        "dataType": "text",
        "displayName": "Image URL",
        "defaultValue": "https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=1200",
        "group": "Content"
      },
      "revealPattern": {
        "dataType": "select",
        "displayName": "Reveal Pattern",
        "defaultValue": "circle",
        "options": ["circle", "diamond", "hexagon", "star", "heart", "wipe-horizontal", "wipe-vertical", "diagonal", "cross", "iris"],
        "group": "Animation"
      },
      "duration": {
        "dataType": "select",
        "displayName": "Animation Duration (ms)",
        "defaultValue": "1500",
        "options": ["800", "1000", "1500", "2000", "2500"],
        "group": "Animation"
      },
      "triggerMode": {
        "dataType": "select",
        "displayName": "Trigger Mode",
        "defaultValue": "scroll",
        "options": ["scroll", "button", "auto"],
        "group": "Content"
      },
      "autoDelay": {
        "dataType": "select",
        "displayName": "Auto Play Delay (s)",
        "defaultValue": "1",
        "options": ["0", "0.5", "1", "1.5", "2"],
        "group": "Animation"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "overlayColor": {
        "dataType": "color",
        "displayName": "Overlay Color",
        "defaultValue": "#495057",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#495057",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const image = config?.image || 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=1200';
  const revealPattern = config?.revealPattern || 'circle';
  const duration = parseInt(config?.duration || '1500');
  const triggerMode = config?.triggerMode || 'scroll';
  const autoDelay = parseFloat(config?.autoDelay || '1') * 1000;
  const backgroundColor = config?.backgroundColor || '#FFFFFF';
  const overlayColor = config?.overlayColor || '#495057';
  const accentColor = config?.accentColor || '#495057';

  const [isRevealed, setIsRevealed] = React.useState(false);
  const [hasScrolled, setHasScrolled] = React.useState(false);

  const containerRef = React.useRef(null);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const getClipPath = (pattern, revealed) => {
    if (revealed) {
      switch (pattern) {
        case 'circle':
          return 'circle(150% at 50% 50%)';
        case 'diamond':
          return 'polygon(0% 50%, 50% 0%, 100% 50%, 50% 100%)';
        case 'hexagon':
          return 'polygon(25% 0%, 75% 0%, 100% 50%, 75% 100%, 25% 100%, 0% 50%)';
        case 'star':
          return 'polygon(50% 0%, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%)';
        case 'heart':
          return 'path("M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z")';
        case 'wipe-horizontal':
          return 'inset(0 0% 0 0)';
        case 'wipe-vertical':
          return 'inset(0% 0 0 0)';
        case 'diagonal':
          return 'polygon(0 0, 100% 0, 100% 100%, 0 100%)';
        case 'cross':
          return 'polygon(0% 0%, 100% 0%, 100% 100%, 0% 100%)';
        case 'iris':
          return 'circle(70.7% at 50% 50%)';
        default:
          return 'circle(150% at 50% 50%)';
      }
    } else {
      switch (pattern) {
        case 'circle':
          return 'circle(0% at 50% 50%)';
        case 'diamond':
          return 'polygon(50% 50%, 50% 50%, 50% 50%, 50% 50%)';
        case 'hexagon':
          return 'polygon(50% 50%, 50% 50%, 50% 50%, 50% 50%, 50% 50%, 50% 50%)';
        case 'star':
          return 'polygon(50% 50%, 50% 50%, 50% 50%, 50% 50%, 50% 50%, 50% 50%, 50% 50%, 50% 50%, 50% 50%, 50% 50%)';
        case 'heart':
          return 'path("M12 12l0 0C12 12 12 12 12 12c0 0 0 0 0 0C12 12 12 12 12 12c0 0 0 0 0 0L12 12z")';
        case 'wipe-horizontal':
          return 'inset(0 100% 0 0)';
        case 'wipe-vertical':
          return 'inset(100% 0 0 0)';
        case 'diagonal':
          return 'polygon(0 0, 0 0, 0 0, 0 0)';
        case 'cross':
          return 'polygon(45% 45%, 55% 45%, 55% 55%, 45% 55%)';
        case 'iris':
          return 'circle(0% at 50% 50%)';
        default:
          return 'circle(0% at 50% 50%)';
      }
    }
  };

  const handleReveal = () => {
    setIsRevealed(true);
  };

  const handleReset = () => {
    setIsRevealed(false);
  };

  React.useEffect(() => {
    if (triggerMode === 'auto') {
      const timer = setTimeout(() => {
        setIsRevealed(true);
      }, autoDelay);
      return () => clearTimeout(timer);
    }
  }, [triggerMode, autoDelay]);

  React.useEffect(() => {
    if (triggerMode === 'scroll' && !hasScrolled) {
      const observer = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting) {
              setIsRevealed(true);
              setHasScrolled(true);
            }
          });
        },
        { threshold: 0.3 }
      );

      if (containerRef.current) {
        observer.observe(containerRef.current);
      }

      return () => observer.disconnect();
    }
  }, [triggerMode, hasScrolled]);

  const getEasing = () => {
    switch (revealPattern) {
      case 'wipe-horizontal':
      case 'wipe-vertical':
        return 'cubic-bezier(0.65, 0, 0.35, 1)';
      case 'circle':
      case 'iris':
        return 'cubic-bezier(0.22, 1, 0.36, 1)';
      default:
        return 'cubic-bezier(0.34, 1.56, 0.64, 1)';
    }
  };

  return (
    <div style={{
      width: '100%',
      minHeight: '100vh',
      backgroundColor: backgroundColor,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      flexDirection: 'column',
      gap: '32px',
      padding: '40px 20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <div
        ref={containerRef}
        style={{
          position: 'relative',
          width: '100%',
          maxWidth: '900px',
          aspectRatio: '16/9',
          borderRadius: '12px',
          overflow: 'hidden',
          boxShadow: '0 8px 24px rgba(0, 0, 0, 0.15)',
          backgroundColor: overlayColor
        }}
      >
        <div style={{
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: '24px',
          fontWeight: '500',
          color: '#FFFFFF',
          opacity: isRevealed ? 0 : 1,
          transition: `opacity ${duration}ms ease-out`,
          pointerEvents: 'none',
          zIndex: 1
        }}>
          {triggerMode === 'button' ? 'Click reveal to start' : 'Revealing...'}
        </div>

        <img
          src={image}
          alt="Reveal"
          style={{
            width: '100%',
            height: '100%',
            objectFit: 'cover',
            clipPath: prefersReducedMotion ? 'none' : getClipPath(revealPattern, isRevealed),
            transition: prefersReducedMotion ? 'none' : `clip-path ${duration}ms ${getEasing()}`,
            willChange: 'clip-path'
          }}
        />
      </div>

      <div style={{
        display: 'flex',
        gap: '16px',
        alignItems: 'center'
      }}>
        {triggerMode === 'button' && (
          <>
            <button
              onClick={handleReveal}
              disabled={isRevealed}
              style={{
                padding: '12px 32px',
                backgroundColor: isRevealed ? `${accentColor}40` : accentColor,
                color: '#FFFFFF',
                border: 'none',
                borderRadius: '8px',
                fontSize: '16px',
                fontWeight: '500',
                cursor: isRevealed ? 'not-allowed' : 'pointer',
                transition: 'all 200ms ease-out'
              }}
              onMouseEnter={(e) => {
                if (!isRevealed) {
                  e.currentTarget.style.transform = 'translateY(-2px)';
                  e.currentTarget.style.boxShadow = '0 4px 12px rgba(0, 0, 0, 0.15)';
                }
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'translateY(0)';
                e.currentTarget.style.boxShadow = 'none';
              }}
            >
              Reveal Image
            </button>

            <button
              onClick={handleReset}
              disabled={!isRevealed}
              style={{
                padding: '12px 32px',
                backgroundColor: !isRevealed ? `${accentColor}40` : `${accentColor}20`,
                color: accentColor,
                border: `1px solid ${accentColor}30`,
                borderRadius: '8px',
                fontSize: '16px',
                fontWeight: '500',
                cursor: !isRevealed ? 'not-allowed' : 'pointer',
                transition: 'all 200ms ease-out'
              }}
              onMouseEnter={(e) => {
                if (isRevealed) {
                  e.currentTarget.style.backgroundColor = `${accentColor}30`;
                }
              }}
              onMouseLeave={(e) => {
                if (isRevealed) {
                  e.currentTarget.style.backgroundColor = `${accentColor}20`;
                }
              }}
            >
              Reset
            </button>
          </>
        )}

        {triggerMode !== 'button' && (
          <button
            onClick={handleReset}
            style={{
              padding: '12px 32px',
              backgroundColor: `${accentColor}20`,
              color: accentColor,
              border: `1px solid ${accentColor}30`,
              borderRadius: '8px',
              fontSize: '16px',
              fontWeight: '500',
              cursor: 'pointer',
              transition: 'all 200ms ease-out'
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.backgroundColor = `${accentColor}30`;
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = `${accentColor}20`;
            }}
          >
            Replay Animation
          </button>
        )}
      </div>

      <div style={{
        fontSize: '14px',
        color: accentColor,
        textAlign: 'center',
        maxWidth: '600px'
      }}>
        Pattern: <strong>{revealPattern}</strong> • 
        Duration: <strong>{duration}ms</strong> • 
        Trigger: <strong>{triggerMode}</strong>
      </div>
    </div>
  );
}

media-videoplayer:
const MANIFEST = {
  "type": "Media.VideoPlayer",
  "description": "Advanced video player with custom controls, keyboard shortcuts, quality selector, playback speed, and picture-in-picture support",
  "editorElement": {
    "selector": ".video-player-container",
    "displayName": "Video Player with Controls",
    "archetype": "container",
    "data": {
      "videoUrl": {
        "dataType": "text",
        "displayName": "Video URL",
        "defaultValue": "https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4",
        "group": "Content"
      },
      "posterUrl": {
        "dataType": "text",
        "displayName": "Poster Image URL",
        "defaultValue": "",
        "group": "Content",
        "description": "Thumbnail shown before play"
      },
      "title": {
        "dataType": "text",
        "displayName": "Video Title",
        "defaultValue": "Sample Video",
        "group": "Content"
      },
      "showTitle": {
        "dataType": "booleanValue",
        "displayName": "Show Title",
        "defaultValue": "true",
        "group": "Content"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#0A0A0A",
        "group": "Colors"
      },
      "controlsBackground": {
        "dataType": "color",
        "displayName": "Controls Background",
        "defaultValue": "rgba(0,0,0,0.8)",
        "group": "Colors"
      },
      "controlsColor": {
        "dataType": "color",
        "displayName": "Controls Icon Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "progressColor": {
        "dataType": "color",
        "displayName": "Progress Bar Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "progressBackground": {
        "dataType": "color",
        "displayName": "Progress Background",
        "defaultValue": "rgba(255,255,255,0.3)",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "fontFamily": {
        "dataType": "select",
        "displayName": "Font Family",
        "defaultValue": "-apple-system, SF Pro, Segoe UI, sans-serif",
        "options": [
          "-apple-system, SF Pro, Segoe UI, sans-serif",
          "Inter, sans-serif",
          "Helvetica Neue, Arial, sans-serif"
        ],
        "group": "Typography"
      },
      "fontSize": {
        "dataType": "select",
        "displayName": "Font Size",
        "defaultValue": "14px",
        "options": ["12px", "14px", "16px"],
        "group": "Typography"
      },
      "cornerRadius": {
        "dataType": "select",
        "displayName": "Corner Radius",
        "defaultValue": "8px",
        "options": ["0px", "4px", "6px", "8px", "12px"],
        "group": "Layout"
      },
      "autoplay": {
        "dataType": "booleanValue",
        "displayName": "Autoplay",
        "defaultValue": "false",
        "group": "Playback"
      },
      "loop": {
        "dataType": "booleanValue",
        "displayName": "Loop",
        "defaultValue": "false",
        "group": "Playback"
      },
      "muted": {
        "dataType": "booleanValue",
        "displayName": "Start Muted",
        "defaultValue": "false",
        "group": "Playback"
      },
      "showQualitySelector": {
        "dataType": "booleanValue",
        "displayName": "Show Quality Selector",
        "defaultValue": "true",
        "group": "Features"
      },
      "showPlaybackSpeed": {
        "dataType": "booleanValue",
        "displayName": "Show Playback Speed",
        "defaultValue": "true",
        "group": "Features"
      },
      "enablePictureInPicture": {
        "dataType": "booleanValue",
        "displayName": "Enable Picture-in-Picture",
        "defaultValue": "true",
        "group": "Features"
      },
      "enableKeyboardShortcuts": {
        "dataType": "booleanValue",
        "displayName": "Enable Keyboard Shortcuts",
        "defaultValue": "true",
        "group": "Features"
      },
      "controlsHideDelay": {
        "dataType": "number",
        "displayName": "Controls Hide Delay (ms)",
        "defaultValue": "3000",
        "group": "Animation"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const videoRef = React.useRef(null);
  const containerRef = React.useRef(null);
  const [isPlaying, setIsPlaying] = React.useState(false);
  const [currentTime, setCurrentTime] = React.useState(0);
  const [duration, setDuration] = React.useState(0);
  const [volume, setVolume] = React.useState(1);
  const [isMuted, setIsMuted] = React.useState(config?.muted !== false);
  const [isFullscreen, setIsFullscreen] = React.useState(false);
  const [showControls, setShowControls] = React.useState(true);
  const [showVolumeSlider, setShowVolumeSlider] = React.useState(false);
  const [playbackRate, setPlaybackRate] = React.useState(1);
  const [showSpeedMenu, setShowSpeedMenu] = React.useState(false);
  const hideControlsTimeout = React.useRef(null);

  const autoplay = config?.autoplay === true;
  const loop = config?.loop === true;
  const enablePiP = config?.enablePictureInPicture !== false;
  const enableKeyboard = config?.enableKeyboardShortcuts !== false;
  const hideDelay = parseInt(config?.controlsHideDelay || '3000');

  // Initialize video
  React.useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    video.volume = volume;
    video.muted = isMuted;
    video.loop = loop;
    if (autoplay) video.play().catch(() => {});

    const handleLoadedMetadata = () => setDuration(video.duration);
    const handleTimeUpdate = () => setCurrentTime(video.currentTime);
    const handlePlay = () => setIsPlaying(true);
    const handlePause = () => setIsPlaying(false);

    video.addEventListener('loadedmetadata', handleLoadedMetadata);
    video.addEventListener('timeupdate', handleTimeUpdate);
    video.addEventListener('play', handlePlay);
    video.addEventListener('pause', handlePause);

    return () => {
      video.removeEventListener('loadedmetadata', handleLoadedMetadata);
      video.removeEventListener('timeupdate', handleTimeUpdate);
      video.removeEventListener('play', handlePlay);
      video.removeEventListener('pause', handlePause);
    };
  }, [autoplay, loop, volume, isMuted]);

  // Handle controls visibility
  const resetControlsTimer = () => {
    setShowControls(true);
    if (hideControlsTimeout.current) {
      clearTimeout(hideControlsTimeout.current);
    }
    if (isPlaying) {
      hideControlsTimeout.current = setTimeout(() => {
        setShowControls(false);
      }, hideDelay);
    }
  };

  React.useEffect(() => {
    return () => {
      if (hideControlsTimeout.current) {
        clearTimeout(hideControlsTimeout.current);
      }
    };
  }, []);

  // Keyboard shortcuts
  React.useEffect(() => {
    if (!enableKeyboard) return;

    const handleKeyPress = (e) => {
      if (e.target.tagName === 'INPUT') return;

      switch (e.key.toLowerCase()) {
        case ' ':
        case 'k':
          e.preventDefault();
          togglePlay();
          break;
        case 'f':
          e.preventDefault();
          toggleFullscreen();
          break;
        case 'm':
          e.preventDefault();
          toggleMute();
          break;
        case 'arrowleft':
          e.preventDefault();
          skip(-5);
          break;
        case 'arrowright':
          e.preventDefault();
          skip(5);
          break;
        case 'arrowup':
          e.preventDefault();
          changeVolume(0.1);
          break;
        case 'arrowdown':
          e.preventDefault();
          changeVolume(-0.1);
          break;
      }
    };

    document.addEventListener('keydown', handleKeyPress);
    return () => document.removeEventListener('keydown', handleKeyPress);
  }, [enableKeyboard, isPlaying]);

  // Playback controls
  const togglePlay = () => {
    const video = videoRef.current;
    if (!video) return;

    if (isPlaying) {
      video.pause();
    } else {
      video.play();
    }
  };

  const skip = (seconds) => {
    const video = videoRef.current;
    if (!video) return;
    video.currentTime = Math.max(0, Math.min(video.duration, video.currentTime + seconds));
    resetControlsTimer();
  };

  const seek = (time) => {
    const video = videoRef.current;
    if (!video) return;
    video.currentTime = time;
  };

  const changeVolume = (delta) => {
    const newVolume = Math.max(0, Math.min(1, volume + delta));
    setVolume(newVolume);
    if (videoRef.current) {
      videoRef.current.volume = newVolume;
    }
    if (newVolume > 0) setIsMuted(false);
    resetControlsTimer();
  };

  const toggleMute = () => {
    setIsMuted(!isMuted);
    if (videoRef.current) {
      videoRef.current.muted = !isMuted;
    }
  };

  const changePlaybackRate = (rate) => {
    setPlaybackRate(rate);
    if (videoRef.current) {
      videoRef.current.playbackRate = rate;
    }
    setShowSpeedMenu(false);
  };

  const toggleFullscreen = () => {
    const container = containerRef.current;
    if (!container) return;

    if (!document.fullscreenElement) {
      container.requestFullscreen?.();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen?.();
      setIsFullscreen(false);
    }
  };

  const togglePictureInPicture = async () => {
    const video = videoRef.current;
    if (!video || !enablePiP) return;

    try {
      if (document.pictureInPictureElement) {
        await document.exitPictureInPicture();
      } else {
        await video.requestPictureInPicture();
      }
    } catch (err) {
      console.error('PiP error:', err);
    }
  };

  // Format time
  const formatTime = (seconds) => {
    if (!isFinite(seconds)) return '0:00';
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div
      ref={containerRef}
      className="video-player-container"
      onMouseMove={resetControlsTimer}
      onMouseLeave={() => isPlaying && setShowControls(false)}
      style={{
        fontFamily: config?.fontFamily || '-apple-system, SF Pro, Segoe UI, sans-serif',
        backgroundColor: config?.backgroundColor || '#0A0A0A',
        borderRadius: config?.cornerRadius || '8px',
        overflow: 'hidden',
        position: 'relative',
        width: '100%',
        maxWidth: '1200px',
        margin: '0 auto'
      }}
    >
      {/* Title overlay */}
      {config?.showTitle !== false && config?.title && (
        <div style={{
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          background: 'linear-gradient(to bottom, rgba(0,0,0,0.6), transparent)',
          padding: '24px',
          zIndex: 2,
          opacity: showControls ? 1 : 0,
          transition: 'opacity 250ms ease-out'
        }}>
          <h3 style={{
            fontSize: '18px',
            fontWeight: '400',
            color: config?.textColor || '#FFFFFF',
            margin: 0
          }}>
            {config?.title}
          </h3>
        </div>
      )}

      {/* Video element */}
      <video
        ref={videoRef}
        src={config?.videoUrl || 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4'}
        poster={config?.posterUrl || ''}
        onClick={togglePlay}
        style={{
          width: '100%',
          height: 'auto',
          display: 'block',
          cursor: 'pointer'
        }}
      />

      {/* Controls overlay */}
      <div style={{
        position: 'absolute',
        bottom: 0,
        left: 0,
        right: 0,
        background: config?.controlsBackground || 'rgba(0,0,0,0.8)',
        padding: '16px',
        zIndex: 2,
        opacity: showControls ? 1 : 0,
        transition: 'opacity 250ms ease-out',
        pointerEvents: showControls ? 'auto' : 'none'
      }}>
        {/* Progress bar */}
        <div
          onClick={(e) => {
            const rect = e.currentTarget.getBoundingClientRect();
            const percent = (e.clientX - rect.left) / rect.width;
            seek(percent * duration);
          }}
          style={{
            width: '100%',
            height: '4px',
            backgroundColor: config?.progressBackground || 'rgba(255,255,255,0.3)',
            borderRadius: '2px',
            cursor: 'pointer',
            marginBottom: '12px',
            position: 'relative'
          }}
        >
          <div style={{
            width: `${(currentTime / duration) * 100}%`,
            height: '100%',
            backgroundColor: config?.progressColor || '#FFFFFF',
            borderRadius: '2px',
            transition: 'width 100ms linear'
          }} />
        </div>

        {/* Controls */}
        <div style={{
          display: 'flex',
          alignItems: 'center',
          gap: '12px',
          fontSize: config?.fontSize || '14px',
          color: config?.textColor || '#FFFFFF'
        }}>
          {/* Play/Pause */}
          <button
            onClick={togglePlay}
            style={{
              background: 'none',
              border: 'none',
              color: config?.controlsColor || '#FFFFFF',
              cursor: 'pointer',
              padding: 0,
              width: '24px',
              height: '24px'
            }}
            aria-label={isPlaying ? 'Pause' : 'Play'}
          >
            {isPlaying ? '⏸' : '▶'}
          </button>

          {/* Skip backward */}
          <button
            onClick={() => skip(-5)}
            style={{
              background: 'none',
              border: 'none',
              color: config?.controlsColor || '#FFFFFF',
              cursor: 'pointer',
              padding: 0,
              fontSize: '18px'
            }}
            aria-label="Skip backward 5 seconds"
          >
            ⏪
          </button>

          {/* Skip forward */}
          <button
            onClick={() => skip(5)}
            style={{
              background: 'none',
              border: 'none',
              color: config?.controlsColor || '#FFFFFF',
              cursor: 'pointer',
              padding: 0,
              fontSize: '18px'
            }}
            aria-label="Skip forward 5 seconds"
          >
            ⏩
          </button>

          {/* Volume */}
          <div
            onMouseEnter={() => setShowVolumeSlider(true)}
            onMouseLeave={() => setShowVolumeSlider(false)}
            style={{ position: 'relative', display: 'flex', alignItems: 'center', gap: '8px' }}
          >
            <button
              onClick={toggleMute}
              style={{
                background: 'none',
                border: 'none',
                color: config?.controlsColor || '#FFFFFF',
                cursor: 'pointer',
                padding: 0,
                fontSize: '18px'
              }}
              aria-label={isMuted ? 'Unmute' : 'Mute'}
            >
              {isMuted || volume === 0 ? '🔇' : volume < 0.5 ? '🔉' : '🔊'}
            </button>

            {showVolumeSlider && (
              <input
                type="range"
                min="0"
                max="1"
                step="0.01"
                value={volume}
                onChange={(e) => {
                  const val = parseFloat(e.target.value);
                  setVolume(val);
                  if (videoRef.current) videoRef.current.volume = val;
                  if (val > 0) setIsMuted(false);
                }}
                style={{
                  width: '80px',
                  cursor: 'pointer'
                }}
              />
            )}
          </div>

          {/* Time */}
          <span style={{ fontSize: '13px', minWidth: '100px' }}>
            {formatTime(currentTime)} / {formatTime(duration)}
          </span>

          <div style={{ flex: 1 }} />

          {/* Playback speed */}
          {config?.showPlaybackSpeed !== false && (
            <div style={{ position: 'relative' }}>
              <button
                onClick={() => setShowSpeedMenu(!showSpeedMenu)}
                style={{
                  background: 'none',
                  border: 'none',
                  color: config?.controlsColor || '#FFFFFF',
                  cursor: 'pointer',
                  padding: '4px 8px',
                  fontSize: '13px'
                }}
              >
                {playbackRate}x
              </button>

              {showSpeedMenu && (
                <div style={{
                  position: 'absolute',
                  bottom: '100%',
                  right: 0,
                  marginBottom: '8px',
                  backgroundColor: config?.controlsBackground || 'rgba(0,0,0,0.9)',
                  borderRadius: '4px',
                  padding: '8px',
                  minWidth: '80px'
                }}>
                  {[0.5, 0.75, 1, 1.25, 1.5, 2].map(rate => (
                    <button
                      key={rate}
                      onClick={() => changePlaybackRate(rate)}
                      style={{
                        background: 'none',
                        border: 'none',
                        color: config?.textColor || '#FFFFFF',
                        cursor: 'pointer',
                        padding: '6px 12px',
                        width: '100%',
                        textAlign: 'left',
                        fontSize: '13px',
                        opacity: playbackRate === rate ? 1 : 0.7
                      }}
                    >
                      {rate}x
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* Picture in Picture */}
          {enablePiP && (
            <button
              onClick={togglePictureInPicture}
              style={{
                background: 'none',
                border: 'none',
                color: config?.controlsColor || '#FFFFFF',
                cursor: 'pointer',
                padding: 0,
                fontSize: '18px'
              }}
              aria-label="Picture in Picture"
            >
              📺
            </button>
          )}

          {/* Fullscreen */}
          <button
            onClick={toggleFullscreen}
            style={{
              background: 'none',
              border: 'none',
              color: config?.controlsColor || '#FFFFFF',
              cursor: 'pointer',
              padding: 0,
              fontSize: '18px'
            }}
            aria-label={isFullscreen ? 'Exit fullscreen' : 'Enter fullscreen'}
          >
            {isFullscreen ? '⊡' : '⛶'}
          </button>
        </div>
      </div>
    </div>
  );
}

media-videoplayercustomcontrols:
const MANIFEST = {
  "type": "Media.VideoPlayerCustomControls",
  "description": "Video player with custom controls, progress bar, volume control, and playback speed",
  "editorElement": {
    "selector": ".video-player-custom",
    "displayName": "Video Player Custom",
    "archetype": "container",
    "data": {
      "videoUrl": {
        "dataType": "text",
        "displayName": "Video URL",
        "defaultValue": "https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4",
        "group": "Content"
      },
      "posterUrl": {
        "dataType": "text",
        "displayName": "Poster Image URL",
        "defaultValue": "https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=1200",
        "group": "Content"
      },
      "autoplay": {
        "dataType": "booleanValue",
        "displayName": "Autoplay",
        "defaultValue": false,
        "group": "Content"
      },
      "showControls": {
        "dataType": "booleanValue",
        "displayName": "Show Controls",
        "defaultValue": true,
        "group": "Content"
      },
      "showTimeDisplay": {
        "dataType": "booleanValue",
        "displayName": "Show Time Display",
        "defaultValue": true,
        "group": "Content"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#000000",
        "group": "Colors"
      },
      "controlsColor": {
        "dataType": "color",
        "displayName": "Controls Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "progressColor": {
        "dataType": "color",
        "displayName": "Progress Color",
        "defaultValue": "#3B82F6",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#495057",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const videoUrl = config?.videoUrl || 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4';
  const posterUrl = config?.posterUrl || 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=1200';
  const autoplay = config?.autoplay === true;
  const showControls = config?.showControls !== false;
  const showTimeDisplay = config?.showTimeDisplay !== false;
  const backgroundColor = config?.backgroundColor || '#000000';
  const controlsColor = config?.controlsColor || '#FFFFFF';
  const progressColor = config?.progressColor || '#3B82F6';
  const accentColor = config?.accentColor || '#495057';

  const [isPlaying, setIsPlaying] = React.useState(false);
  const [currentTime, setCurrentTime] = React.useState(0);
  const [duration, setDuration] = React.useState(0);
  const [volume, setVolume] = React.useState(1);
  const [isMuted, setIsMuted] = React.useState(false);
  const [playbackSpeed, setPlaybackSpeed] = React.useState(1);
  const [isFullscreen, setIsFullscreen] = React.useState(false);
  const [showVolumeSlider, setShowVolumeSlider] = React.useState(false);
  const [showSpeedMenu, setShowSpeedMenu] = React.useState(false);
  const [buffered, setBuffered] = React.useState(0);

  const videoRef = React.useRef(null);
  const containerRef = React.useRef(null);
  const progressRef = React.useRef(null);

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const togglePlay = () => {
    if (videoRef.current) {
      if (isPlaying) {
        videoRef.current.pause();
      } else {
        videoRef.current.play();
      }
      setIsPlaying(!isPlaying);
    }
  };

  const handleTimeUpdate = () => {
    if (videoRef.current) {
      setCurrentTime(videoRef.current.currentTime);

      if (videoRef.current.buffered.length > 0) {
        const bufferedEnd = videoRef.current.buffered.end(videoRef.current.buffered.length - 1);
        setBuffered((bufferedEnd / videoRef.current.duration) * 100);
      }
    }
  };

  const handleLoadedMetadata = () => {
    if (videoRef.current) {
      setDuration(videoRef.current.duration);
    }
  };

  const handleProgressClick = (e) => {
    if (progressRef.current && videoRef.current) {
      const rect = progressRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const percentage = x / rect.width;
      const time = percentage * duration;
      videoRef.current.currentTime = time;
      setCurrentTime(time);
    }
  };

  const handleVolumeChange = (e) => {
    const newVolume = parseFloat(e.target.value);
    setVolume(newVolume);
    if (videoRef.current) {
      videoRef.current.volume = newVolume;
    }
    if (newVolume === 0) {
      setIsMuted(true);
    } else if (isMuted) {
      setIsMuted(false);
    }
  };

  const toggleMute = () => {
    if (videoRef.current) {
      videoRef.current.muted = !isMuted;
      setIsMuted(!isMuted);
    }
  };

  const changePlaybackSpeed = (speed) => {
    if (videoRef.current) {
      videoRef.current.playbackRate = speed;
      setPlaybackSpeed(speed);
      setShowSpeedMenu(false);
    }
  };

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      containerRef.current?.requestFullscreen();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  const skipTime = (seconds) => {
    if (videoRef.current) {
      videoRef.current.currentTime += seconds;
    }
  };

  const handleKeyDown = (e) => {
    switch (e.key) {
      case ' ':
        e.preventDefault();
        togglePlay();
        break;
      case 'ArrowLeft':
        skipTime(-10);
        break;
      case 'ArrowRight':
        skipTime(10);
        break;
      case 'm':
        toggleMute();
        break;
      case 'f':
        toggleFullscreen();
        break;
    }
  };

  React.useEffect(() => {
    const video = videoRef.current;
    if (video) {
      video.addEventListener('timeupdate', handleTimeUpdate);
      video.addEventListener('loadedmetadata', handleLoadedMetadata);

      return () => {
        video.removeEventListener('timeupdate', handleTimeUpdate);
        video.removeEventListener('loadedmetadata', handleLoadedMetadata);
      };
    }
  }, []);

  const progressPercentage = (currentTime / duration) * 100;

  return (
    <div style={{
      width: '100%',
      minHeight: '100vh',
      backgroundColor: backgroundColor,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '40px 20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <div
        ref={containerRef}
        onKeyDown={handleKeyDown}
        tabIndex={0}
        style={{
          position: 'relative',
          width: '100%',
          maxWidth: '1000px',
          aspectRatio: '16/9',
          backgroundColor: '#000000',
          borderRadius: '12px',
          overflow: 'hidden',
          boxShadow: '0 8px 24px rgba(0, 0, 0, 0.3)',
          outline: 'none'
        }}
      >
        <video
          ref={videoRef}
          src={videoUrl}
          poster={posterUrl}
          autoPlay={autoplay}
          onClick={togglePlay}
          style={{
            width: '100%',
            height: '100%',
            objectFit: 'contain',
            cursor: 'pointer'
          }}
        />

        {!isPlaying && (
          <div
            onClick={togglePlay}
            style={{
              position: 'absolute',
              top: '50%',
              left: '50%',
              transform: 'translate(-50%, -50%)',
              width: '80px',
              height: '80px',
              borderRadius: '50%',
              backgroundColor: 'rgba(255, 255, 255, 0.9)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              cursor: 'pointer',
              transition: 'transform 200ms ease-out',
              boxShadow: '0 4px 12px rgba(0, 0, 0, 0.3)'
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.transform = 'translate(-50%, -50%) scale(1.1)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = 'translate(-50%, -50%) scale(1)';
            }}
          >
            <div style={{
              width: 0,
              height: 0,
              borderLeft: '24px solid #000000',
              borderTop: '16px solid transparent',
              borderBottom: '16px solid transparent',
              marginLeft: '6px'
            }} />
          </div>
        )}

        {showControls && (
          <div style={{
            position: 'absolute',
            bottom: 0,
            left: 0,
            right: 0,
            background: 'linear-gradient(to top, rgba(0,0,0,0.8), transparent)',
            padding: '40px 20px 20px',
            backdropFilter: 'blur(4px)'
          }}>
            <div
              ref={progressRef}
              onClick={handleProgressClick}
              style={{
                width: '100%',
                height: '6px',
                backgroundColor: 'rgba(255, 255, 255, 0.3)',
                borderRadius: '3px',
                marginBottom: '16px',
                cursor: 'pointer',
                position: 'relative'
              }}
            >
              <div style={{
                position: 'absolute',
                top: 0,
                left: 0,
                height: '100%',
                width: `${buffered}%`,
                backgroundColor: 'rgba(255, 255, 255, 0.5)',
                borderRadius: '3px',
                transition: 'width 200ms ease-out'
              }} />

              <div style={{
                position: 'absolute',
                top: 0,
                left: 0,
                height: '100%',
                width: `${progressPercentage}%`,
                backgroundColor: progressColor,
                borderRadius: '3px',
                transition: 'width 100ms ease-out'
              }} />

              <div style={{
                position: 'absolute',
                top: '50%',
                left: `${progressPercentage}%`,
                transform: 'translate(-50%, -50%)',
                width: '14px',
                height: '14px',
                backgroundColor: progressColor,
                borderRadius: '50%',
                boxShadow: '0 2px 8px rgba(0, 0, 0, 0.3)',
                transition: 'left 100ms ease-out'
              }} />
            </div>

            <div style={{
              display: 'flex',
              alignItems: 'center',
              gap: '12px',
              color: controlsColor
            }}>
              <button
                onClick={togglePlay}
                style={{
                  background: 'none',
                  border: 'none',
                  color: controlsColor,
                  fontSize: '24px',
                  cursor: 'pointer',
                  padding: '8px',
                  display: 'flex',
                  alignItems: 'center'
                }}
              >
                {isPlaying ? '⏸' : '▶'}
              </button>

              <button
                onClick={() => skipTime(-10)}
                style={{
                  background: 'none',
                  border: 'none',
                  color: controlsColor,
                  fontSize: '18px',
                  cursor: 'pointer',
                  padding: '8px'
                }}
                title="Back 10s"
              >
                ⏪
              </button>

              <button
                onClick={() => skipTime(10)}
                style={{
                  background: 'none',
                  border: 'none',
                  color: controlsColor,
                  fontSize: '18px',
                  cursor: 'pointer',
                  padding: '8px'
                }}
                title="Forward 10s"
              >
                ⏩
              </button>

              {showTimeDisplay && (
                <span style={{ fontSize: '14px', fontFamily: 'monospace', minWidth: '100px' }}>
                  {formatTime(currentTime)} / {formatTime(duration)}
                </span>
              )}

              <div style={{ flex: 1 }} />

              <div
                style={{ position: 'relative' }}
                onMouseEnter={() => setShowVolumeSlider(true)}
                onMouseLeave={() => setShowVolumeSlider(false)}
              >
                <button
                  onClick={toggleMute}
                  style={{
                    background: 'none',
                    border: 'none',
                    color: controlsColor,
                    fontSize: '20px',
                    cursor: 'pointer',
                    padding: '8px'
                  }}
                >
                  {isMuted || volume === 0 ? '🔇' : volume < 0.5 ? '🔉' : '🔊'}
                </button>

                {showVolumeSlider && (
                  <div style={{
                    position: 'absolute',
                    bottom: '100%',
                    left: '50%',
                    transform: 'translateX(-50%)',
                    marginBottom: '8px',
                    padding: '12px 8px',
                    backgroundColor: 'rgba(0, 0, 0, 0.9)',
                    borderRadius: '8px',
                    height: '100px'
                  }}>
                    <input
                      type="range"
                      min="0"
                      max="1"
                      step="0.1"
                      value={volume}
                      onChange={handleVolumeChange}
                      style={{
                        WebkitAppearance: 'slider-vertical',
                        width: '4px',
                        height: '80px',
                        cursor: 'pointer'
                      }}
                    />
                  </div>
                )}
              </div>

              <div style={{ position: 'relative' }}>
                <button
                  onClick={() => setShowSpeedMenu(!showSpeedMenu)}
                  style={{
                    background: 'none',
                    border: 'none',
                    color: controlsColor,
                    fontSize: '14px',
                    cursor: 'pointer',
                    padding: '8px',
                    fontWeight: '500'
                  }}
                >
                  {playbackSpeed}x
                </button>

                {showSpeedMenu && (
                  <div style={{
                    position: 'absolute',
                    bottom: '100%',
                    right: 0,
                    marginBottom: '8px',
                    backgroundColor: 'rgba(0, 0, 0, 0.9)',
                    borderRadius: '8px',
                    overflow: 'hidden',
                    minWidth: '80px'
                  }}>
                    {[0.5, 0.75, 1, 1.25, 1.5, 2].map(speed => (
                      <button
                        key={speed}
                        onClick={() => changePlaybackSpeed(speed)}
                        style={{
                          width: '100%',
                          padding: '8px 12px',
                          background: speed === playbackSpeed ? 'rgba(255, 255, 255, 0.2)' : 'none',
                          border: 'none',
                          color: controlsColor,
                          fontSize: '14px',
                          cursor: 'pointer',
                          textAlign: 'left'
                        }}
                      >
                        {speed}x
                      </button>
                    ))}
                  </div>
                )}
              </div>

              <button
                onClick={toggleFullscreen}
                style={{
                  background: 'none',
                  border: 'none',
                  color: controlsColor,
                  fontSize: '20px',
                  cursor: 'pointer',
                  padding: '8px'
                }}
                title="Fullscreen"
              >
                {isFullscreen ? '⛶' : '⛶'}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

