  const containerMaxWidth = config?.containerMaxWidth || "900px";
  const imageAspectRatio = config?.imageAspectRatio || "16/9";
  const backgroundColor = config?.backgroundColor || "#FAFAFA";
  const containerBackground = config?.containerBackground || "#FFFFFF";
  const lensBorderColor = config?.lensBorderColor || "#FFFFFF";
  const lensShadowColor = config?.lensShadowColor || "rgba(0,0,0,0.3)";
  const instructionTextColor = config?.instructionTextColor || "#6C757D";

  const [showLens, setShowLens] = React.useState(false);
  const [lensPosition, setLensPosition] = React.useState({ x: 0, y: 0 });
  const [imageLoaded, setImageLoaded] = React.useState(false);
  const imageRef = React.useRef(null);
  const containerRef = React.useRef(null);

  const smoothnessValues = {
    instant: 0,
    smooth: 100,
    medium: 150,
    slow: 250
  };

  const transitionDuration = smoothnessValues[smoothness] || 150;

  const handleMouseMove = (e) => {
    if (!enableMagnifier || !imageRef.current) return;

    const rect = imageRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    // Check if mouse is within image bounds
    if (x >= 0 && x <= rect.width && y >= 0 && y <= rect.height) {
      setLensPosition({ x, y });
      if (!showLens) setShowLens(true);
    } else {
      setShowLens(false);
    }
  };

  const handleMouseLeave = () => {
    setShowLens(false);
  };

  const handleTouchMove = (e) => {
    if (!enableMagnifier || !imageRef.current) return;

    const touch = e.touches[0];
    const rect = imageRef.current.getBoundingClientRect();
    const x = touch.clientX - rect.left;
    const y = touch.clientY - rect.top;

    if (x >= 0 && x <= rect.width && y >= 0 && y <= rect.height) {
      setLensPosition({ x, y });
      if (!showLens) setShowLens(true);
    }
  };

  const getLensStyle = () => {
    if (!imageRef.current) return {};

    const rect = imageRef.current.getBoundingClientRect();

    // Calculate background position for magnified view
    const bgX = (lensPosition.x / rect.width) * 100;
    const bgY = (lensPosition.y / rect.height) * 100;

    return {
      position: 'absolute',
      width: `${lensSize}px`,
      height: `${lensSize}px`,
      borderRadius: '50%',
      border: `${lensBorder}px solid ${lensBorderColor}`,
      backgroundImage: `url(${imageUrl})`,
      backgroundSize: `${rect.width * zoomLevel}px ${rect.height * zoomLevel}px`,
      backgroundPosition: `${bgX}% ${bgY}%`,
      backgroundRepeat: 'no-repeat',
      pointerEvents: 'none',
      left: `${lensPosition.x - lensSize / 2}px`,
      top: `${lensPosition.y - lensSize / 2}px`,
      opacity: showLens && imageLoaded ? 1 : 0,
      transform: showLens && imageLoaded ? 'scale(1)' : 'scale(0.8)',
      transition: `all ${transitionDuration}ms ease-out`,
      boxShadow: `0 8px 24px ${lensShadowColor}`,
      zIndex: 10,
      willChange: 'transform, opacity'
    };
  };

  return (
    <div className="image-magnifier" style={{
      minHeight: '100vh',
      width: '100%',
      backgroundColor,
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '3rem 1.5rem',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <div style={{
        maxWidth: containerMaxWidth,
        width: '100%',
        backgroundColor: containerBackground,
        borderRadius: '8px',
        padding: '2rem',
        boxShadow: '0 1px 3px rgba(0,0,0,0.06)'
      }}>
        <div
          ref={containerRef}
          style={{
            position: 'relative',
            width: '100%',
            aspectRatio: imageAspectRatio,
            overflow: 'hidden',
            borderRadius: '6px',
            cursor: enableMagnifier ? 'crosshair' : 'default',
            backgroundColor: '#F8F9FA'
          }}
          onMouseMove={handleMouseMove}
          onMouseLeave={handleMouseLeave}
          onTouchMove={handleTouchMove}
          onTouchEnd={handleMouseLeave}
        >
          <img
            ref={imageRef}
            src={imageUrl}
            alt={altText}
            onLoad={() => setImageLoaded(true)}
            style={{
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              display: 'block',
              userSelect: 'none'
            }}
            draggable={false}
          />

          {enableMagnifier && (
            <div style={getLensStyle()} />
          )}

          {enableMagnifier && !showLens && imageLoaded && (
            <div style={{
              position: 'absolute',
              bottom: '1.5rem',
              left: '50%',
              transform: 'translateX(-50%)',
              backgroundColor: 'rgba(255, 255, 255, 0.95)',
              backdropFilter: 'blur(10px)',
              padding: '0.75rem 1.5rem',
              borderRadius: '6px',
              fontSize: '0.875rem',
              fontWeight: '400',
              color: instructionTextColor,
              boxShadow: '0 2px 8px rgba(0,0,0,0.08)',
              opacity: 1,
              animation: 'fadeIn 400ms ease-out',
              pointerEvents: 'none'
            }}>
              Hover over the image to magnify
            </div>
          )}
        </div>

        <div style={{
          marginTop: '1.5rem',
          display: 'flex',
          gap: '2rem',
          fontSize: '0.875rem',
          color: '#6C757D',
          justifyContent: 'center'
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <span style={{
              width: '8px',
              height: '8px',
              borderRadius: '50%',
              backgroundColor: enableMagnifier ? '#212529' : '#CED4DA'
            }} />
            <span>Zoom: {zoomLevel}x</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <span style={{
              width: '8px',
              height: '8px',
              borderRadius: '50%',
              backgroundColor: '#212529'
            }} />
            <span>Lens: {lensSize}px</span>
          </div>
        </div>
      </div>

      <style>{`
        @keyframes fadeIn {
          from {
            opacity: 0;
            transform: translateX(-50%) translateY(10px);
          }
          to {
            opacity: 1;
            transform: translateX(-50%) translateY(0);
          }
        }

        @media (prefers-reduced-motion: reduce) {
          .image-magnifier * {
            animation: none !important;
            transition: none !important;
          }
        }
      `}</style>
    </div>
  );
}

