const MANIFEST = {
  "type": "Media.ChromaticCanvas",
  "description": "Canvas slideshow with chromatic aberration effects",
  "editorElement": {
    "selector": ".chromatic-canvas",
    "displayName": "Chromatic Canvas",
    "archetype": "container",
    "data": {
      "images": {
        "dataType": "text",
