        "defaultValue": "https://picsum.photos/1200/800?random=1,https://picsum.photos/1200/800?random=2,https://picsum.photos/1200/800?random=3",
        "group": "Content"
      },
      "intensity": {
        "dataType": "select",
        "displayName": "Effect Intensity",
        "defaultValue": "1.5",
        "options": ["0.5", "1.0", "1.5", "2.0"],
        "group": "Effects"
      },
      "duration": {
        "dataType": "select",
        "displayName": "Transition Duration (ms)",
        "defaultValue": "1200",
        "options": ["800", "1000", "1200", "1500"],
        "group": "Effects"
      },
      "height": {
        "dataType": "select",
        "displayName": "Height",
        "defaultValue": "600px",
        "options": ["400px", "500px", "600px", "700px", "800px"],
        "group": "Layout"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const imgs = (config?.images || "https://picsum.photos/1200/800?random=1,https://picsum.photos/1200/800?random=2,https://picsum.photos/1200/800?random=3").split(',').map(function(u){return u.trim();});
  const intensity = parseFloat(config?.intensity || "1.5");
  const duration = parseInt(config?.duration || "1200");
  const height = config?.height || "600px";

  const canvasRef = React.useRef(null);
  const containerRef = React.useRef(null);
  const pixiRef = React.useRef(null);
  const spritesRef = React.useRef([]);
  const filtersRef = React.useRef([]);
  const rafRef = React.useRef(null);

  const [idx, setIdx] = React.useState(0);
  const [loading, setLoading] = React.useState(true);
  const [ready, setReady] = React.useState(false);
  const [transitioning, setTransitioning] = React.useState(false);

  const shader = "precision highp float;varying vec2 vTextureCoord;uniform sampler2D uSampler;uniform float uIntensity;vec2 distort(vec2 uv,float k,float kc){vec2 t=uv-0.5;float r2=dot(t,t);float f=1.0+r2*(k+kc*sqrt(r2));return f*t+0.5;}vec3 sample(vec2 uv){if(uv.x<0.0||uv.x>1.0||uv.y<0.0||uv.y>1.0)return vec3(0.0);return texture2D(uSampler,uv).rgb;}void main(){vec2 uv=vTextureCoord;if(uIntensity<0.01){gl_FragColor=texture2D(uSampler,uv);return;}float k=-1.5*uIntensity;float kc=0.5*uIntensity;float o=0.1*uIntensity;float r=sample(distort(uv,k+o,kc)).r;float g=sample(distort(uv,k,kc)).g;float b=sample(distort(uv,k-o,kc)).b;gl_FragColor=vec4(r,g,b,1.0);}";

  React.useEffect(function() {
    if (!canvasRef.current || !containerRef.current) return;
    let mounted = true;

    async function init() {
      try {
        if (!window.PIXI) {
          await new Promise(function(res, rej) {
            const s = document.createElement('script');
            s.src = 'https://cdnjs.cloudflare.com/ajax/libs/pixi.js/6.5.8/browser/pixi.min.js';
            s.onload = res;
            s.onerror = rej;
            document.head.appendChild(s);
          });
        }
        if (!mounted) return;

        const P = window.PIXI;
        const w = containerRef.current.clientWidth;
        const h = containerRef.current.clientHeight;

        const app = new P.Application({
          view: canvasRef.current,
          width: w,
          height: h,
          resolution: window.devicePixelRatio || 1,
          autoDensity: true,
          backgroundColor: 0x1a1a1a,
          backgroundAlpha: 1
        });

        pixiRef.current = app;

        const sprites = [];
        const filters = [];

        for (let i = 0; i < imgs.length; i++) {
          const tex = await P.Texture.fromURL(imgs[i]);
          const spr = new P.Sprite(tex);
          const flt = new P.Filter(undefined, shader, { uIntensity: 0.0 });

          spr.filters = [flt];
          spr.alpha = i === 0 ? 1 : 0;

          const sc = Math.max(w / tex.width, h / tex.height);
          spr.width = tex.width * sc;
          spr.height = tex.height * sc;
          spr.x = (w - spr.width) / 2;
          spr.y = (h - spr.height) / 2;

          app.stage.addChild(spr);
          sprites.push(spr);
          filters.push(flt);
        }

        spritesRef.current = sprites;
        filtersRef.current = filters;

        if (mounted) {
          setReady(true);
          setLoading(false);
        }
      } catch (e) {
        console.error(e);
        if (mounted) setLoading(false);
      }
    }

    init();

    return function() {
      mounted = false;
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      if (pixiRef.current) pixiRef.current.destroy(true);
    };
  }, [imgs.join(',')]);

  function transition(newIdx) {
    if (!ready || transitioning || newIdx === idx) return;
    if (newIdx < 0 || newIdx >= spritesRef.current.length) return;

    console.log('TRANSITION START:', idx, '->', newIdx);
    setTransitioning(true);

    const curr = spritesRef.current[idx];
    const next = spritesRef.current[newIdx];
    const currF = filtersRef.current[idx];
    const nextF = filtersRef.current[newIdx];

    const start = Date.now();

    curr.alpha = 1;
    next.alpha = 0;
    currF.uniforms.uIntensity = 0;
    nextF.uniforms.uIntensity = 0;

    console.log('Start state:', { currAlpha: curr.alpha, nextAlpha: next.alpha, currEffect: currF.uniforms.uIntensity, nextEffect: nextF.uniforms.uIntensity });

    function anim() {
      const elapsed = Date.now() - start;
      const prog = Math.min(elapsed / duration, 1);

      const fx = Math.sin(prog * Math.PI) * intensity;
      currF.uniforms.uIntensity = fx;
      nextF.uniforms.uIntensity = fx;

      const ease = prog * prog * (3 - 2 * prog);
      curr.alpha = 1 - ease;
      next.alpha = ease;

      if (Math.abs(prog - 0.5) < 0.01) {
        console.log('Midpoint:', { prog: prog, fx: fx, currAlpha: curr.alpha, nextAlpha: next.alpha });
      }

      if (prog < 1) {
        rafRef.current = requestAnimationFrame(anim);
      } else {
        curr.alpha = 0;
        next.alpha = 1;
        currF.uniforms.uIntensity = 0;
        nextF.uniforms.uIntensity = 0;
        console.log('TRANSITION END');
        setIdx(newIdx);
        setTransitioning(false);
      }
    }
    anim();
  }

  function prev() { transition(idx === 0 ? imgs.length - 1 : idx - 1); }
  function next() { transition(idx === imgs.length - 1 ? 0 : idx + 1); }

  return React.createElement('div', { style: { padding: '40px 24px', maxWidth: '1400px', margin: '0 auto', position: 'relative' } },
    React.createElement('div', { ref: containerRef, style: { position: 'relative', width: '100%', height: height, background: '#1a1a1a', borderRadius: '8px', overflow: 'hidden' } },
      React.createElement('canvas', { ref: canvasRef, style: { display: 'block', width: '100%', height: '100%', position: 'absolute', top: 0, left: 0 } }),
      loading && React.createElement('div', { style: { position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff', zIndex: 100 } }, 'Loading images...'),
      ready && React.createElement(React.Fragment, null,
        React.createElement('button', { onClick: prev, style: { position: 'absolute', left: '16px', top: '50%', transform: 'translateY(-50%)', width: '48px', height: '48px', borderRadius: '50%', border: 'none', background: 'rgba(255,255,255,0.2)', color: '#fff', fontSize: '24px', cursor: 'pointer', zIndex: 10 } }, '‹'),
        React.createElement('button', { onClick: next, style: { position: 'absolute', right: '16px', top: '50%', transform: 'translateY(-50%)', width: '48px', height: '48px', borderRadius: '50%', border: 'none', background: 'rgba(255,255,255,0.2)', color: '#fff', fontSize: '24px', cursor: 'pointer', zIndex: 10 } }, '›'),
        React.createElement('div', { style: { position: 'absolute', bottom: '16px', left: '50%', transform: 'translateX(-50%)', display: 'flex', gap: '12px', padding: '8px 16px', borderRadius: '24px', background: 'rgba(0,0,0,0.5)', zIndex: 10 } },
          imgs.map(function(_, i) {
            return React.createElement('button', { key: i, onClick: function() { transition(i); }, style: { width: i === idx ? '24px' : '8px', height: '8px', borderRadius: i === idx ? '4px' : '50%', border: 'none', background: '#fff', opacity: i === idx ? 1 : 0.4, cursor: 'pointer', padding: 0, transition: 'all 200ms' } });
          })
        )
      )
    ),
    ready && React.createElement('div', { style: { marginTop: '24px', padding: '20px', background: '#fff', border: '1px solid #ddd', borderRadius: '8px', textAlign: 'center' } },
      React.createElement('strong', null, 'Chromatic Aberration Slideshow'),
      React.createElement('div', { style: { marginTop: '8px' } }, 'Image ', idx + 1, ' of ', imgs.length),
      React.createElement('div', { style: { marginTop: '8px', fontSize: '12px', color: '#666' } }, transitioning ? 'Transitioning...' : 'Ready')
    )
  );
}

