  "editorElement": {
    "selector": ".mouse-following-reveal",
    "displayName": "Mouse Following Image Reveal",
    "archetype": "container",
    "data": {
      "baseImage": {
        "dataType": "text",
        "displayName": "Base Image URL",
        "defaultValue": "https://images.unsplash.com/photo-1519681393784-d120267933ba?w=1920&q=80",
