      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const baseImage = config?.baseImage || "https://images.unsplash.com/photo-1519681393784-d120267933ba?w=1920&q=80";
  const revealImage = config?.revealImage || "https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=1920&q=80";
  const headlineText = config?.headlineText || "Explore the Hidden";
  const subheadText = config?.subheadText || "Move your cursor to reveal";
  const maskRadius = parseInt(config?.maskRadius || "200");
  const followSpeed = parseFloat(config?.followSpeed || "0.15");
  const baseImageOverlay = config?.baseImageOverlay || "rgba(0,0,0,0.3)";
  const textColor = config?.textColor || "#FFFFFF";
  const headlineFontSize = parseInt(config?.headlineFontSize || "64");
  const subheadFontSize = parseInt(config?.subheadFontSize || "20");
  const fontWeight = config?.fontWeight || "400";
  const enableGlow = config?.enableGlow !== false;
  const glowColor = config?.glowColor || "#3B82F6";

  const [mousePos, setMousePos] = React.useState({ x: 0, y: 0 });
  const [maskPos, setMaskPos] = React.useState({ x: 0, y: 0 });
  const containerRef = React.useRef(null);
  const rafRef = React.useRef(null);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  React.useEffect(() => {
    if (prefersReducedMotion) return;

    const handleMouseMove = (e) => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      setMousePos({
        x: e.clientX - rect.left,
        y: e.clientY - rect.top
      });
    };

    const container = containerRef.current;
    if (container) {
      container.addEventListener('mousemove', handleMouseMove, { passive: true });
    }

    return () => {
      if (container) {
        container.removeEventListener('mousemove', handleMouseMove);
      }
    };
  }, [prefersReducedMotion]);

  React.useEffect(() => {
    if (prefersReducedMotion) {
      setMaskPos(mousePos);
      return;
    }

    const animate = () => {
      setMaskPos(prev => ({
        x: prev.x + (mousePos.x - prev.x) * followSpeed,
        y: prev.y + (mousePos.y - prev.y) * followSpeed
      }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);

    return () => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
      }
    };
  }, [mousePos, followSpeed, prefersReducedMotion]);

  return (
    <div
      ref={containerRef}
      className="mouse-following-reveal"
      style={{
        position: 'relative',
        width: '100%',
        height: '100vh',
        overflow: 'hidden',
        cursor: 'none'
      }}
    >
      {/* Base Image Layer */}
      <div
        style={{
          position: 'absolute',
          inset: 0,
          backgroundImage: `url(${baseImage})`,
          backgroundSize: 'cover',
          backgroundPosition: 'center'
        }}
      >
        <div style={{
          position: 'absolute',
          inset: 0,
          backgroundColor: baseImageOverlay
        }} />
      </div>

      {/* Reveal Image Layer with Mask */}
      <div
        style={{
          position: 'absolute',
          inset: 0,
          backgroundImage: `url(${revealImage})`,
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          clipPath: `circle(${maskRadius}px at ${maskPos.x}px ${maskPos.y}px)`,
          WebkitClipPath: `circle(${maskRadius}px at ${maskPos.x}px ${maskPos.y}px)`,
          transition: prefersReducedMotion ? 'none' : 'clip-path 0.1s ease-out',
          filter: enableGlow ? `drop-shadow(0 0 ${maskRadius * 0.3}px ${glowColor})` : 'none'
        }}
      />

      {/* Text Content Overlay */}
      <div
        style={{
          position: 'absolute',
          inset: 0,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          textAlign: 'center',
          padding: '0 32px',
          pointerEvents: 'none'
        }}
      >
        <h1
          style={{
            fontSize: `clamp(${headlineFontSize * 0.5}px, ${headlineFontSize * 0.08}vw + ${headlineFontSize * 0.4}px, ${headlineFontSize}px)`,
            fontWeight: fontWeight,
            color: textColor,
            margin: 0,
            marginBottom: '16px',
            fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
            letterSpacing: '0.02em',
            textShadow: '0 2px 12px rgba(0,0,0,0.3)'
          }}
        >
          {headlineText}
        </h1>
        <p
          style={{
            fontSize: `${subheadFontSize}px`,
            fontWeight: '300',
            color: textColor,
            margin: 0,
            fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
            opacity: 0.9,
            textShadow: '0 1px 8px rgba(0,0,0,0.3)'
          }}
        >
          {subheadText}
        </p>
      </div>

      {/* Custom Cursor */}
      <div
        style={{
          position: 'absolute',
          left: maskPos.x,
          top: maskPos.y,
          width: '12px',
          height: '12px',
          borderRadius: '50%',
          backgroundColor: enableGlow ? glowColor : textColor,
          transform: 'translate(-50%, -50%)',
          pointerEvents: 'none',
          opacity: 0.8,
          boxShadow: enableGlow ? `0 0 16px ${glowColor}` : 'none',
          transition: prefersReducedMotion ? 'none' : 'transform 0.1s ease-out'
        }}
      />
    </div>
  );
}
